from z3 import *

n = 22
# Create boolean variables for each possible edge
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i,j)] = Bool(f"e_{i}_{j}")

def get_edge(u, v):
    if u > v:
        u, v = v, u
    return edges[(u, v)]

solver = Solver()

# Degree constraints: each vertex has degree between 4 and 5
for v in range(n):
    edge_vars = []
    for u in range(v):
        edge_vars.append(edges[(u,v)])
    for w in range(v+1, n):
        edge_vars.append(edges[(v,w)])

    # Degree >= 4
    solver.add(Sum([If(e, 1, 0) for e in edge_vars]) >= 4)
    # Degree <= 5
    solver.add(Sum([If(e, 1, 0) for e in edge_vars]) <= 5)

# No triangles (cycles of length 3)
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            solver.add(Not(And(edges[(i,j)], edges[(j,k)], edges[(i,k)])))

# No 4-cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                # All possible 4-cycles among 4 vertices
                solver.add(Not(And(get_edge(i,j), get_edge(j,k), get_edge(k,l), get_edge(i,l))))
                solver.add(Not(And(get_edge(i,j), get_edge(j,l), get_edge(k,l), get_edge(i,k))))
                solver.add(Not(And(get_edge(i,k), get_edge(k,j), get_edge(j,l), get_edge(i,l))))

print("Constraints added. Checking satisfiability...")
print(f"Number of edge variables: {len(edges)}")

result = solver.check()
print(f"Result: {result}")

