from z3 import *

n = 22
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i,j)] = Bool(f"e_{i}_{j}")

def get_edge(u, v):
    if u > v:
        u, v = v, u
    return edges[(u, v)]

solver = Solver()

# Degree constraints
for v in range(n):
    edge_vars = []
    for u in range(v):
        edge_vars.append(edges[(u,v)])
    for w in range(v+1, n):
        edge_vars.append(edges[(v,w)])
    solver.add(Sum([If(e, 1, 0) for e in edge_vars]) >= 4)
    solver.add(Sum([If(e, 1, 0) for e in edge_vars]) <= 5)

# No triangles (3-cycles)
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            solver.add(Not(And(edges[(i,j)], edges[(j,k)], edges[(i,k)])))

# No 4-cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                solver.add(Not(And(get_edge(i,j), get_edge(j,k), get_edge(k,l), get_edge(i,l))))
                solver.add(Not(And(get_edge(i,j), get_edge(j,l), get_edge(k,l), get_edge(i,k))))
                solver.add(Not(And(get_edge(i,k), get_edge(k,j), get_edge(j,l), get_edge(i,l))))

# No 5-cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                for m in range(l+1, n):
                    # All possible 5-cycles among 5 vertices
                    # A 5-cycle is a Hamiltonian cycle on 5 vertices
                    # There are (5-1)!/2 = 12 distinct 5-cycles on 5 labeled vertices
                    cycles = [
                        [i,j,k,l,m], [i,j,k,m,l], [i,j,l,k,m],
                        [i,j,l,m,k], [i,j,m,k,l], [i,j,m,l,k],
                        [i,k,j,l,m], [i,k,j,m,l], [i,k,l,j,m],
                        [i,k,l,m,j], [i,k,m,j,l], [i,k,m,l,j],
                    ]
                    for cycle in cycles:
                        cycle_edges = [get_edge(cycle[t], cycle[(t+1)%5]) for t in range(5)]
                        solver.add(Not(And(*cycle_edges)))

print("Added 3, 4, 5-cycle constraints. Checking...")
result = solver.check()
print(f"Result: {result}")
